365	        errors.push({ what: `"taskScheduler.dailyHour" must be an integer 0–23 (UTC), got ${JSON.stringify(dailyHour)}`, fix: 'set an hour of the day, 0 through 23' });
366	      }
367	      if (weeklyDay !== undefined && !SCHEDULE_WEEKDAYS.includes(weeklyDay)) {
368	        errors.push({ what: `"taskScheduler.weeklyDay" must be one of ${SCHEDULE_WEEKDAYS.join(', ')}, got ${JSON.stringify(weeklyDay)}`, fix: 'name a weekday, e.g. "Sun"' });
369	      }
370	      if (monthlyDay !== undefined && !(Number.isInteger(monthlyDay) && monthlyDay >= 1 && monthlyDay <= 31)) {
371	        errors.push({ what: `"taskScheduler.monthlyDay" must be an integer 1–31, got ${JSON.stringify(monthlyDay)}`, fix: 'set a day of the month, 1 through 31 (clamped to the month length)' });
372	      }
373	      // The tasks this repo does not want instantiated (docs/PRINCIPLES.md,
374	      // "What is not a precondition"). Repo shape — "this repo ships the store
375	      // pipeline", "this repo has a vendored mount" — is a fact adoption settled,
376	      // so it is answered once here rather than re-asked by a precondition every
377	      // night. Validated as a shape only: whether the named task exists is a
378	      // question about the repo's declared packs, answered where tasks are
379	      // discovered, and a member may legitimately disable a task it has not
380	      // adopted yet.
381	      const { disabledTasks } = raw.taskScheduler;
382	      if (disabledTasks !== undefined
383	          && !(Array.isArray(disabledTasks)
384	            && disabledTasks.every((id) => typeof id === 'string' && /^[^/\s]+\/[^/\s]+$/.test(id)))) {
385	        errors.push({
386	          what: `"taskScheduler.disabledTasks" must be an array of "<pack>/<task>" ids, got ${JSON.stringify(disabledTasks)}`,
387	          fix: 'list the tasks this repo does not run, e.g. ["claudinite-lifecycle/update"]',
388	        });
389	      }
390	
391	      const { dispatch } = raw.taskScheduler;
392	      const endpoints = raw.taskScheduler[ENDPOINTS_KEY] ?? raw.taskScheduler[LEGACY_ENDPOINTS_KEY];
393	      if (dispatch !== undefined && !DISPATCH_MODES.includes(dispatch)) {
394	        errors.push({
395	          what: `"taskScheduler.dispatch" must be one of ${DISPATCH_MODES.join(', ')}, got ${JSON.stringify(dispatch)}`,
396	          fix: 'omit the key — the work-item queue is the only dispatch mechanism; "slots" named the slot scheduler, which is deleted',
397	        });
398	      }
399	      // The endpoint map (docs/PRINCIPLES.md): a name → { url, tokenSecret }.
400	      // `tokenSecret` is the NAME of a repo Actions secret and never a value —
401	      // that indirection is the whole reason a task may declare an endpoint at all,
402	      // since a task declaration is vendored verbatim into every consuming repo.
403	      if (endpoints !== undefined) {
404	        if (endpoints === null || typeof endpoints !== 'object' || Array.isArray(endpoints)) {
405	          errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}" must be an object of endpoint name → { url, tokenSecret }`, fix: 'e.g. { "default": { "url": "https://…", "tokenSecret": "CCR_SESSION_TOKEN" } }' });
406	        } else {
407	          for (const [epName, entry] of Object.entries(endpoints)) {
408	            if (entry === null || typeof entry !== 'object' || Array.isArray(entry)
409	                || typeof entry.url !== 'string' || typeof entry.tokenSecret !== 'string') {
410	              errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}.${epName}" must be { url, tokenSecret } (both strings)`, fix: 'give the endpoint an invocation URL and the NAME of the repo Actions secret holding its token — never the token itself' });
411	            }
412	          }
413	        }
414	      }
415	      taskScheduler = raw.taskScheduler;
416	    }
417	  }
418	
419	  // --- the installed mount: the engine version this repo holds, and the version of
420	  // each pack it has installed. The current home is the top-level `engineVersion`
421	  // and each pack entry's own `version`; the retired `claudinite` block is read
422	  // underneath for a member the #1252 record has not reached, and a pack renamed
423	  // since that block was written still keys its version under the old spelling, so
424	  // the legacy map is canonicalized before anything compares it.
425	  let engineVersion = null;
426	  if (raw.engineVersion !== undefined) {
427	    if (isVersion(raw.engineVersion)) engineVersion = raw.engineVersion;
428	    else {
429	      errors.push({
430	        what: `"engineVersion" must be a version — date-anchored <day>.<n>, got ${JSON.stringify(raw.engineVersion)}`,
431	        fix: 'leave it to the update flows, which write the version they installed',
432	      });
433	    }
434	  } else if (isVersion(raw.claudinite?.engineVersion)) {
435	    engineVersion = raw.claudinite.engineVersion;
436	  }
437	
438	  const packVersions = {};
439	  const legacyVersions = raw.claudinite?.packVersions;
440	  if (legacyVersions && typeof legacyVersions === 'object' && !Array.isArray(legacyVersions)) {
441	    Object.assign(packVersions, canonicalPackVersions(legacyVersions));
442	  }
443	  for (const entry of packEntries) {
444	    if (entry.version !== undefined) packVersions[entry.id] = entry.version;
445	  }
446	
447	  // --- the delivery override. `true` is the only value that means anything, so
448	  // anything else present is a typo the run must not read as "yes" or silently as
449	  // "no" — a wrong answer here is a PR merged unreviewed on a repo that asked for
450	  // review, or a repo's daily update stalled forever waiting for a human nobody
451	  // told. The retired `maintenance.delivery` says the same thing the old way, and
452	  // an unrecognised value THERE is equally an error rather than a default.
453	  let requirePrReview = false;
454	  if (raw.dailyClaudiniteUpdatesRequirePrReview !== undefined) {
455	    if (typeof raw.dailyClaudiniteUpdatesRequirePrReview === 'boolean') {
456	      requirePrReview = raw.dailyClaudiniteUpdatesRequirePrReview;
457	    } else {
458	      errors.push({
459	        what: `"dailyClaudiniteUpdatesRequirePrReview" must be true or false, got ${JSON.stringify(raw.dailyClaudiniteUpdatesRequirePrReview)}`,
460	        fix: 'set it to true to leave this repo\'s update PR for a human, or remove the key',
461	      });
462	    }
463	  } else if (raw.maintenance?.delivery !== undefined) {
464	    const legacy = String(raw.maintenance.delivery).trim();
465	    if (['review', 'pr'].includes(legacy)) requirePrReview = true;
466	    else if (!['auto-merge', 'auto', 'push', ''].includes(legacy)) {
467	      errors.push({
468	        what: `the retired "maintenance.delivery" holds ${JSON.stringify(raw.maintenance.delivery)}, which is neither auto-merge nor review`,
469	        fix: 'remove the "maintenance" block — set "dailyClaudiniteUpdatesRequirePrReview": true if this repo\'s update PR must wait for a human',
470	      });
471	    }
472	  }
473	
474	  return {
475	    packs,
476	    packEntries,
477	    rules,
478	    accept,
479	    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
480	    packConfig,
481	    taskScheduler,
482	    // The installed mount, normalized from wherever this member happens to spell
483	    // it: the top-level `engineVersion` and each entry's own `version`, falling
484	    // back to the retired `claudinite` block for a member that has not run the
485	    // #1252 record yet. Downstream reads ONE shape and never learns there were
486	    // two — and omitting a declared key from this returned shape is the worst
487	    // kind of bug, legal to write and impossible to read: it is what made the
488	    // stamp invisible to the scheduler and silently killed baselining fleet-wide,
489	    // every repo self-skipping as "no vendored mount" while its runs went green.
490	    // The CONFIG_KEYS-survive-loadConfig test pins the whole set.
491	    engineVersion,
492	    packVersions,
493	    // The harsh override, normalized to the boolean every caller asks for and named
494	    // exactly as the file names it — one spelling, so nothing has to learn that the
495	    // key and the field it loads into are different words. Absent is the normal
496	    // shape and means the update PR lands on its own; the retired
497	    // `maintenance.delivery: review` says the same thing the old way.
498	    dailyClaudiniteUpdatesRequirePrReview: requirePrReview,
499	    // The declaration exactly as the member wrote it. The engine normalizes what the
500	    // engine OWNS; a setting belonging to a pack is that pack's to read, and its
501	    // reader needs the unnormalized file — both to find a parameter on a pack entry
502	    // and to resolve a retired top-level spelling the engine deliberately no longer
503	    // folds. Every caller that has a shape to ask about should ask its owner's
504	    // predicate, not reach in here.
505	    raw,
506	    errors,
507	  };
508	}
