510	export function buildContext({ root, mode = 'changed', baseOverride = null, transcriptPath = null }) {
511	  root = resolve(root);
512	  const baseRef = baseOverride || resolveBaseRef(root);
513	  refreshBaseRef(root, baseRef);
514	  const mergeBase = baseRef ? (gitTry(root, 'merge-base', 'HEAD', baseRef) || '').trim() || null : null;
515	  // Diffing against HEAD keeps uncommitted work in scope even when no base branch resolves.
516	  const diffBase = mergeBase || 'HEAD';
517	  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
518	  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
519	  // be on it, so nothing is filtered out.
520	  const onBaseBranch = (sha) =>
521	    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;
522	
523	  const tracked = lines(gitTry(root, 'ls-files'));
524	  const untracked = lines(gitTry(root, 'ls-files', '--others', '--exclude-standard'));
525	
526	  const vsBase = lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase));
527	  let scanned;
528	  if (mode === 'all') {
529	    scanned = [...tracked, ...untracked];
530	  } else {
531	    scanned = [...new Set([...vsBase, ...untracked])];
532	  }
533	  // The vendored corpus under the shared mount is canon-owned, never the
534	  // project's own code — structurally out of scope for every check, on any git
535	  // host and any checkout (deliberately not attribute-driven). The consumer's
536	  // own .claudinite/local/packs/ sits BESIDE the shared mount and stays fully
537	  // in scope.
538	  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
539	  // with the platform separator, so normalize before prefix-matching.
540	  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;
541	  scanned = scanned.filter((f) => !f.startsWith(sharedPrefix));
542	  // Every in-scope regular file, vendored/generated included.
543	  const allFiles = scanned.filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile());
544	  // The default sweep excludes vendored/generated files, so `ctx.files` is the
545	  // project's OWN authored code and every check skips them for free (see vendoredSet).
546	  const vendored = vendoredSet(root, allFiles);
547	  const files = allFiles.filter((f) => !vendored.has(f));
548	  // The in-scope files the current change touched (vs the scoping base),
549	  // untracked included — the file set behind lines.mjs addedLines, for
550	  // check-the-work rules that judge the work rather than re-audit the world.
551	  const changedSet = new Set([...vsBase, ...untracked]);
552	  const changedFiles = files.filter((f) => changedSet.has(f));
553	
554	  const deleted = mergeBase ? lines(gitTry(root, 'diff', '--name-only', '--diff-filter=D', mergeBase)) : [];
555	
556	  let commits = [];
557	  if (mergeBase) {
558	    const out = gitTry(root, 'log', '--format=%s%n%b%x00', `${mergeBase}..HEAD`);
559	    commits = (out || '').split('\0').map((m) => m.trim()).filter(Boolean);
560	  }
561	
562	  const branch = (gitTry(root, 'rev-parse', '--abbrev-ref', 'HEAD') || '').trim();
563	
564	  // Conversation surface: the Stop hook forwards the session's transcript_path;
565	  // every other surface (CI, a manual run) has none, and conversation rules must
566	  // return [] when this is null. Parsed lazily and cached — most sweeps never ask.
567	  let conversationCache;
568	  let sessionEntriesCache;
569	
570	  // Checks are read-only over an immutable snapshot of the tree, so file and
571	  // base-blob reads are cached for the sweep: many rules re-read the same files,
572	  // and each readBase is otherwise a git subprocess.
573	  const readCache = new Map();
574	  const readBaseCache = new Map();
575	
576	  return {
577	    root,
578	    mode,
579	    baseRef,
580	    mergeBase,
581	    files,
582	    allFiles,
583	    changedFiles,
584	    tracked,
585	    untracked,
586	    deleted,
587	    commits,
588	    branch,
589	    config: loadConfig(root),
590	
591	    exists: (path) => existsSync(join(root, path)),
592	    read(path) {
593	      if (!readCache.has(path)) {
594	        let text;
595	        try { text = readFileSync(join(root, path), 'utf8'); } catch { text = null; }
596	        readCache.set(path, text);
597	      }
598	      return readCache.get(path);
599	    },
600	
601	    // File content at the scoping base (the merge-base with the base branch), or
602	    // null if the file didn't exist there or no base resolves. Lets a delta
603	    // check compare structured state — e.g. a manifest's permission set — against
604	    // the baseline precisely, immune to text-diff line noise (JSON trailing
605	    // commas make appending an array element re-touch the previous line).
606	    readBase(path) {
607	      if (!mergeBase) return null;
608	      if (!readBaseCache.has(path)) readBaseCache.set(path, gitTry(root, 'show', `${mergeBase}:${path}`));
609	      return readBaseCache.get(path);
610	    },
611	
612	    // Added lines of one file relative to the scoping base (untracked file = every line).
613	    addedLines(file) {
614	      if (!tracked.includes(file)) {
615	        const text = this.read(file);
616	        return text === null ? [] : text.split('\n').map((t, i) => ({ line: i + 1, text: t }));
617	      }
618	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
619	      const added = [];
620	      let lineNo = 0;
621	      for (const l of (out || '').split('\n')) {
622	        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
623	        if (hunk) { lineNo = Number(hunk[1]); continue; }
624	        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
625	        else if (!l.startsWith('-')) lineNo += l ? 1 : 0;
626	      }
627	      return added;
628	    },
629	
630	    // The lines the change REMOVES from a tracked file, numbered as the base
631	    // had them — the diff's "-" side, the mirror of addedLines. A file the
632	    // base did not hold removed nothing.
633	    removedLines(file) {
634	      if (!mergeBase || !tracked.includes(file)) return [];
635	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
636	      const removed = [];
637	      let lineNo = 0;
638	      for (const l of (out || '').split('\n')) {
639	        const hunk = /^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@/.exec(l);
640	        if (hunk) { lineNo = Number(hunk[1]); continue; }
641	        if (l.startsWith('-') && !l.startsWith('---')) { removed.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
642	        else if (!l.startsWith('+')) lineNo += l ? 1 : 0;
643	      }
644	      return removed;
645	    },
646	
647	    // Parsed transcript entries of the session driving this run, or null when no
648	    // transcript is available (see conversationCache above).
649	    conversation() {
650	      if (conversationCache !== undefined) return conversationCache;
651	      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
652	      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
653	      catch { conversationCache = null; }
654	      return conversationCache;
655	    },
656	
657	    // Every entry the session wrote — the transcript above plus each subagent
658	    // stream beside it — for the rules that judge what the session DID: the
659	    // skills it loaded, the calls it made. `conversation()` stays the session
660	    // file alone, since that is where the owner's turns are. Empty on a surface
661	    // with no transcript, which `conversation()` is what distinguishes from a
662	    // session that did nothing.
663	    sessionEntries() {
664	      if (sessionEntriesCache === undefined) {
665	        sessionEntriesCache = sessionTranscriptPaths(transcriptPath).flatMap((path) => {
666	          // A stream unreadable mid-write costs its own entries, never the others'.
667	          try { return parseEntries(readFileSync(path, 'utf8')); } catch { return []; }
668	        });
669	      }
670	      return sessionEntriesCache;
671	    },
672	
673	    // The branch's own commits since the merge-base, oldest first, each with its
674	    // changed files and committer date — for rules about the ORDER work landed in
675	    // (ctx.commits keeps only messages). Merges excluded: their file list is
676	    // empty under --name-only and their content arrives via their parents.
677	    commitsWithFiles() {
678	      if (!mergeBase) return [];
679	      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
680	        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase}..HEAD`);
681	      const commits = [];
682	      for (const block of (out || '').split('\0')) {
683	        if (!block.trim()) continue;
684	        const [head, ...rest] = block.trim().split('\n');
685	        const [sha, date, subject] = head.split('\x1f');
686	        commits.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
687	      }
688	      return commits;
689	    },
690	
691	    // Merge commits the current change introduces — those on HEAD's first-parent
692	    // chain since the merge-base with the base branch (the squash-only effect
693	    // check, scoped to the work). Empty when no base resolves or the branch is
694	    // even with it; pre-existing merges already on the base are out of range.
695	    //
696	    // The range alone trusts the merge-base to be right, and it isn't always: a
697	    // shallow clone's grafted boundary or a criss-cross history can hand back a
698	    // merge-base that sweeps the base branch's own merges into the range. So each
699	    // candidate is confirmed against the base ref itself — a merge already on the
700	    // base branch was never introduced here, whatever the range says. Offline and
701	    // exact, and it holds when refreshBaseRef couldn't run.
702	    introducedMergeCommits() {
703	      if (!mergeBase) return [];
704	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase}..HEAD`);
705	      return lines(out).map((l) => {
706	        const i = l.indexOf(' ');
707	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
708	      }).filter(({ sha }) => !onBaseBranch(sha));
709	    },
710	
711	    // Fixed-string search across tracked files; git grep exits 1 on no match.
712	    // The vendored shared mount is structurally out of the sweep (canon-owned,
713	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
714	    // excluded here exactly as it is from the scanned file set above: a hit
715	    // inside it must never become a finding.
716	    grepTracked(needle) {
717	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
718	      return lines(out).map((l) => {
719	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
720	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
721	      }).filter(Boolean);
722	    },
723	  };
724	}
